"""EXP-LEAD-001 public enquiry, staff lead workflow and notification context."""

def extend_experience(spec):
    from authorization import operation, parameter, object_schema, UUID, VERSION, REF
    model=spec['components']['schemas']; scopes=spec['components']['securitySchemes']['workload']['flows']['clientCredentials']['scopes']
    nullable=lambda schema:{'anyOf':[schema,{'type':'null'}]}
    model['LeadEnquiryInput']=object_schema({'type':{'enum':['CONTACT','COMPLAINT']},'name':{'type':'string','minLength':1,'maxLength':160},'email':{'type':'string','format':'email','maxLength':254},'phone':nullable({'type':'string','pattern':r'^\+[1-9][0-9]{7,14}$'}),'subject':{'type':'string','minLength':1,'maxLength':200},'message':{'type':'string','minLength':1,'maxLength':10000},'antiSpamToken':{'type':'string','minLength':1,'maxLength':4096}})
    model['LeadEnquiryInput']['required']=['type','name','email','subject','message','antiSpamToken']
    model['LeadCreated']=object_schema({'id':UUID,'state':{'const':'NEW'},'receivedAt':{'type':'string','format':'date-time'}})
    model['ExperienceLeadDTO']=object_schema({'id':UUID,'type':{'enum':['CONTACT','COMPLAINT','QUOTE','DISTRIBUTOR']},'subject':{'type':'string','maxLength':200},'name':{'type':'string','maxLength':160},'email':nullable({'type':'string','format':'email','maxLength':254}),'phone':nullable({'type':'string','maxLength':32}),'message':{'type':'string','maxLength':10000},'state':{'enum':['NEW','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED']},'priority':{'enum':['NORMAL','HIGH']},'assignedTo':nullable(UUID),'followUpAt':nullable({'type':'string','format':'date-time'}),'version':VERSION,'createdAt':{'type':'string','format':'date-time'}})
    model['ExperienceLeadActivity']=object_schema({'kind':{'type':'string','maxLength':30},'note':{'type':'string','maxLength':2000},'createdAt':{'type':'string','format':'date-time'}})
    detail=model['ExperienceLeadDTO']['properties'].copy();detail['activities']={'type':'array','maxItems':200,'items':REF('ExperienceLeadActivity')}
    model['ExperienceLeadDetail']=object_schema(detail)
    model['ExperienceLeadPage']=object_schema({'items':{'type':'array','maxItems':100,'items':REF('ExperienceLeadDTO')},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'totalElements':VERSION,'totalPages':VERSION})
    model['ExperienceLeadPatch']=object_schema({'state':{'enum':['NEW','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED']},'assignedTo':nullable(UUID),'priority':{'enum':['NORMAL','HIGH']},'followUpAt':nullable({'type':'string','format':'date-time'}),'note':{'type':'string','minLength':1,'maxLength':2000}})
    model['ExperienceLeadPatch']['required']=['note'];model['ExperienceLeadPatch']['minProperties']=2
    model['ExperienceLeadNotificationContext']=object_schema({'leadId':UUID,'type':{'type':'string','maxLength':20},'subject':{'type':'string','maxLength':200},'recipientGroup':{'type':'string','pattern':r'^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$'},'adminLink':{'type':'string','format':'uri','pattern':'^https://'}})
    idem=parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100,'pattern':r'^[ -~]+$'},True)
    path=parameter('id','path',UUID,True)
    create=operation('API-087','Public CONTACT/COMPLAINT intake. Anti-abuse verifier, rate-limit port and recipient group must be explicitly configured; absent configuration fails closed. Lead, initial activity, audit, idempotency response and redacted EVT-016 commit atomically before notification dispatch. Raw message/contact data is excluded from event, audit and telemetry.','LeadCreated',[idem])
    create['security']=[];create['requestBody']={'required':True,'content':{'application/json':{'schema':REF('LeadEnquiryInput')}}};create['responses']['201']=create['responses'].pop('200');create['responses']['201']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}};create['responses']['429']={'description':'Configured rate limit reached'};create['responses']['503']={'description':'Anti-abuse verifier unavailable; no lead is committed'}
    spec['paths']['/api/v1/enquiries']={'post':create}
    scopes.update({'leads.read_WITH_SIGNED_ACTOR':'Read assigned Experience leads as a current signed SALES actor','leads.update_WITH_SIGNED_ACTOR':'Update an assigned Experience lead as a current signed SALES actor','notification.read':'Read configured Experience lead notification context'})
    listop=operation('API-089','Exact Commerce BFF workload and signed current SALES/ADMIN actor. SALES visibility is limited to assigned and unassigned triage items; filters cannot widen assignment scope. Bounded deterministic pagination; private lead fields are no-store and audited.','ExperienceLeadPage',[parameter('type','query',{'enum':['CONTACT','COMPLAINT','QUOTE','DISTRIBUTOR']}),parameter('state','query',{'enum':['NEW','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED']}),parameter('priority','query',{'enum':['NORMAL','HIGH']}),parameter('assignedTo','query',UUID),parameter('page','query',{'type':'integer','minimum':0,'default':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100,'default':20}),parameter('sort','query',{'type':'string','enum':['createdAt,desc','createdAt,asc','priority,desc','priority,asc','followUpAt,asc','followUpAt,desc'],'default':'createdAt,desc'})])
    listop['security']=[{'workload':['leads.read_WITH_SIGNED_ACTOR'],'signedActor':[]}];listop['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}};spec['paths']['/api/v1/staff/leads']={'get':listop}
    detail=operation('API-090','Exact Commerce BFF workload and signed current SALES/ADMIN actor. Return a lead only to its assigned actor, ADMIN or current triage scope; activity notes are private and append-only.','ExperienceLeadDetail',[path]);detail['security']=[{'workload':['leads.read_WITH_SIGNED_ACTOR'],'signedActor':[]}];detail['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}};spec['paths']['/api/v1/staff/leads/{id}']={'get':detail}
    update=operation('API-091','Exact Commerce BFF workload and signed current SALES/ADMIN actor. Require If-Match and Idempotency-Key; assignment is self-claim only because no cross-owner staff-target validation API is defined. Every accepted change increments version and appends an immutable activity plus redacted audit.','ExperienceLeadDTO',[path,parameter('If-Match','header',{'type':'string','pattern':r'^"(0|[1-9][0-9]{0,18})"$'},True),idem]);update['security']=[{'workload':['leads.update_WITH_SIGNED_ACTOR'],'signedActor':[]}];update['requestBody']={'required':True,'content':{'application/json':{'schema':REF('ExperienceLeadPatch')}}};update['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}},'ETag':{'schema':{'type':'string'}}};spec['paths']['/api/v1/staff/leads/{id}']['patch']=update
    ctx=operation('API-129','Exact nigson-integration workload only; no actor assertion. Return minimum configured recipient context from the committed EVT-016 identity, without complaint message or contact data. HTTPS admin base URL and recipient group are required configuration; missing values fail closed.','ExperienceLeadNotificationContext',[path]);ctx['security']=[{'workload':['notification.read']}];ctx['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}};spec['paths']['/internal/v1/leads/{id}/notification-context']={'get':ctx}
    return spec
